  const error=points=>points.reduce((sum,point)=>sum+(point.y-polynomialValue(conceptState.coefficients,point.x))**2,0)/points.length;
  conceptRender=()=>{conceptState.coefficients=polynomialFit(conceptState.train,conceptState.degree);const trainError=error(conceptState.train),testError=error(conceptState.test),size=conceptSize(),area=conceptArea(size,{left:48,right:18,top:18,bottom:38}),context=conceptContext;context.clearRect(0,0,size.width,size.height);const px=x=>cx(x,area,-1,1),py=y=>cy(y,area,-2.8,2.8);context.strokeStyle=conceptPalette.grid;[-2,-1,0,1,2].forEach(value=>{context.beginPath();context.moveTo(area.x,py(value));context.lineTo(area.x+area.w,py(value));context.stroke()});context.strokeStyle="#91a2b1";context.strokeRect(area.x,area.y,area.w,area.h);context.beginPath();for(let i=0;i<=180;i++){const x=-1+i/90,y=clamp(polynomialValue(conceptState.coefficients,x),-3.5,3.5);i?context.lineTo(px(x),py(y)):context.moveTo(px(x),py(y))}context.strokeStyle=conceptPalette.red;context.lineWidth=3;context.stroke();conceptState.test.forEach(point=>{context.beginPath();context.arc(px(point.x),py(point.y),3.3,0,Math.PI*2);context.fillStyle="#fff";context.fill();context.strokeStyle=conceptPalette.orange;context.lineWidth=1.2;context.stroke()});conceptState.train.forEach(point=>{context.beginPath();context.arc(px(point.x),py(point.y),5,0,Math.PI*2);context.fillStyle=conceptPalette.blue;context.fill();context.strokeStyle="#fff";context.stroke()});context.fillStyle=conceptPalette.muted;context.font="600 12px system-ui";context.fillText("x",area.x+area.w-4,size.height-8);context.fillText("target y",4,area.y+12);let diagnosis="balanced fit";if(trainError>.35&&testError>.4)diagnosis="underfitting";else if(testError>trainError*2.2&&testError>.18)diagnosis="overfitting";metricCards([{label:"Training MSE",value:fmt(trainError,3),note:"Error on fitted examples"},{label:"Test MSE",value:fmt(testError,3),note:"Error on unseen examples"},{label:"Generalization gap",value:fmt(testError-trainError,3),note:"Test minus training"},{label:"Current pattern",value:diagnosis,note:"A heuristic teaching cue"}]);const math=$("#genMath");if(math)math.innerHTML=`Degree <b>${conceptState.degree}</b> gives training MSE <b>${fmt(trainError,3)}</b> and test MSE <b>${fmt(testError,3)}</b>.`};
  regenerate();bindRange("genDegree",value=>conceptState.degree=value,0);bindRange("genSamples",value=>{conceptState.samples=value;regenerate()},0);bindRange("genNoise",value=>{conceptState.noise=value;regenerate()},2);$("#genNew").addEventListener("click",()=>{conceptState.seed++;regenerate();conceptRender()});$("#genSimple").addEventListener("click",()=>{conceptState.degree=2;$("#genDegree").value=2;$("#genDegreeOut").textContent="2";conceptRender()});conceptRender();
