function makeEnsembleData(seed=211,noise=.1){const random=seededRandom(seed);return Array.from({length:31},(_,index)=>{const x=-4.5+index*.3;let label=x>-.9&&x<2.05?1:0;if(random()<noise)label=1-label;return {x,y:(random()-.5)*.14,label}})}
function stumpPredict(stump,x){return stump.direction*(x-stump.threshold)>=0?1:0}
