  thresholds.forEach(threshold=>[-1,1].forEach(direction=>{let error=0;points.forEach((point,index)=>{if(stumpPredict({threshold,direction},point.x)!==point.label)error+=weights[index]});if(error<best.error)best={error,threshold,direction}}));return best;
