function autoencoderPattern(name){const size=8,grid=Array.from({length:size},()=>Array(size).fill(0));for(let row=0;row<size;row++)for(let column=0;column<size;column++){if(name==="x")grid[row][column]=(Math.abs(row-column)<=.5||Math.abs(row+column-(size-1))<=.5)?1:0;else if(name==="box")grid[row][column]=(row===1||row===6||column===1||column===6)?1:0;else if(name==="bars")grid[row][column]=(column===1||column===3||column===6)?1:0;else grid[row][column]=(row===1&&column>=1&&column<=6)||(column===3&&row>=1&&row<=6)?1:0}return grid}
function dctAlpha(index,size){return index===0?Math.sqrt(1/size):Math.sqrt(2/size)}
