function dctOrder(size){return Array.from({length:size*size},(_,index)=>({u:Math.floor(index/size),v:index%size})).sort((a,b)=>(a.u+a.v)-(b.u+b.v)||(((a.u+a.v)%2)?a.u-b.u:a.v-b.v))}
