  const imageMatrix=(context,matrix,x,y,cell,label,editable=false)=>{context.fillStyle=conceptPalette.ink;context.font="800 12px system-ui";context.textAlign="left";context.fillText(label,x,y-11);matrix.forEach((row,rowIndex)=>row.forEach((value,columnIndex)=>{const level=Math.round(249-clamp(value,0,1)*155);context.fillStyle=`rgb(${level},${Math.round(level+clamp(value,0,1)*32)},${Math.round(level+clamp(value,0,1)*45)})`;context.fillRect(x+columnIndex*cell,y+rowIndex*cell,cell,cell);context.strokeStyle="#c4d0d9";context.lineWidth=1;context.strokeRect(x+columnIndex*cell,y+rowIndex*cell,cell,cell)}));if(editable){context.strokeStyle=conceptPalette.ink;context.lineWidth=2;context.strokeRect(x,y,cell*matrix.length,cell*matrix.length)}};
